item.command:
/bin/bash -lc "node - <<'NODE'
const {execFileSync}=require('child_process');
const p=require('./package.json');
const deps={...p.dependencies,...p.devDependencies};
for (const [name, spec] of Object.entries(deps)) {
  try {
    const latest=execFileSync('npm',['view',name,'version'],{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();
    const time=execFileSync('npm',['view',name,"'`time.${latest}`],{encoding:'"'utf8',stdio:['ignore','pipe','pipe']}).trim();
    console.log("'`${name}'"\\t"'${spec}'"\\t"'${latest}'"\\t"'${time}`);
  } catch (e) {
    console.log(`${name}'"\\t"'${spec}'"\\tERROR\\t"'${(e.stderr||e.message).toString().replace(/'"\\s+/g,' ').trim()}"'`);
  }
}
NODE'

